-- 054_injury_programs.sql
-- Nine programs for an injured athlete, one per area (shoulder, elbow, wrist,
-- neck, upper back, lower back, hip, knee, ankle), in French, English and
-- German. None of their exercises loads the area, by the app's injury rules.
-- The app files them on a shelf of their own, "For an injury", by their name.
--
-- Deploy: apply this file, in any order with the code. Online, the app
-- shows the catalogue of this table: the programs appear once it is applied.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Épaule blessée : jambes et abdos', 'Trois séances pour garder le rythme sans solliciter l''épaule : jambes, fessiers, abdos et gainage au sol, rien au-dessus de la tête ni en poussée. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Jambes","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Walking Lunge","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Standing Calf Raise","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Abdos et gainage","exercises":[{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45},{"exerciseName":"Lying Leg Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Bicycle Crunch","targetSets":3,"targetReps":"20","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60}]},{"name":"Fessiers et jambes","exercises":[{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Bulgarian Split Squat","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Flutter Kicks","targetSets":3,"targetReps":"20-30s","restSec":45}]}]'::jsonb, true, 400, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Épaule blessée : jambes et abdos' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
